use crate::wide::I256;

use super::{decide, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^3 with E = 46u + 94u^2 + 66u^3 + 22u^4 + 4u^5, the
/// result's unit error (header), rounded up to an `f64`: 6473924464345094 · 2^-100.
const ERROR: f64 = f64::from_bits(0x3cf7_0000_0000_0006);

/// `tpi_weight`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
) -> Option<Sign> {
    let n2y = rounded_f64(n2y, 83)?;
    let n3z = rounded_f64(n3z, 83)?;
    let c23_x_1 = n2y * n3z;
    let n2z = rounded_f64(n2z, 83)?;
    let n3y = rounded_f64(n3y, 83)?;
    let c23_x_2 = n2z * n3y;
    let c23_x = c23_x_1 - c23_x_2;
    let n3x = rounded_f64(n3x, 83)?;
    let c23_y_1 = n2z * n3x;
    let n2x = rounded_f64(n2x, 83)?;
    let c23_y_2 = n2x * n3z;
    let c23_y = c23_y_1 - c23_y_2;
    let c23_z_1 = n2x * n3y;
    let c23_z_2 = n2y * n3x;
    let c23_z = c23_z_1 - c23_z_2;
    let n1x = rounded_f64(n1x, 83)?;
    let w_1 = n1x * c23_x;
    let n1y = rounded_f64(n1y, 83)?;
    let w_2 = n1y * c23_y;
    let w_3 = w_1 + w_2;
    let n1z = rounded_f64(n1z, 83)?;
    let w_4 = n1z * c23_z;
    let w = w_3 + w_4;
    let m_n1 = largest_magnitude([n1x, n1y, n1z]);
    let m_n2 = largest_magnitude([n2y, n2z, n2x]);
    let m_n3 = largest_magnitude([n3z, n3y, n3x]);
    let scale = m_n1 * m_n2 * m_n3;
    decide(w, ERROR, scale)
}

/// `tpi_weight`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
) -> Option<I256> {
    let n2y = within(n2y, 83)?;
    let n3z = within(n3z, 83)?;
    let c23_x_1 = I256::product_i128(n2y, n3z)?;
    let n2z = within(n2z, 83)?;
    let n3y = within(n3y, 83)?;
    let c23_x_2 = I256::product_i128(n2z, n3y)?;
    let c23_x = c23_x_1.checked_sub(&c23_x_2)?;
    let n3x = within(n3x, 83)?;
    let c23_y_1 = I256::product_i128(n2z, n3x)?;
    let n2x = within(n2x, 83)?;
    let c23_y_2 = I256::product_i128(n2x, n3z)?;
    let c23_y = c23_y_1.checked_sub(&c23_y_2)?;
    let c23_z_1 = I256::product_i128(n2x, n3y)?;
    let c23_z_2 = I256::product_i128(n2y, n3x)?;
    let c23_z = c23_z_1.checked_sub(&c23_z_2)?;
    let n1x = within(n1x, 83)?;
    let w_1 = c23_x.checked_mul_i128(n1x)?;
    let n1y = within(n1y, 83)?;
    let w_2 = c23_y.checked_mul_i128(n1y)?;
    let w_3 = w_1.checked_add(&w_2)?;
    let n1z = within(n1z, 83)?;
    let w_4 = c23_z.checked_mul_i128(n1z)?;
    let w = w_3.checked_add(&w_4)?;
    Some(w)
}

